class Solution {
    public int findMinMoves(int[] machines) {
        int n = machines.length;
        long total = 0;
        for (int dresses : machines) total += dresses;
        if (total % n != 0) return -1;
        int target = (int) (total / n);

        long prefix = 0;
        long expected = 0;
        int answer = 0;
        for (int i = 0; i < n; i++) {
            prefix += machines[i];
            expected += target;
            int boundaryFlow = (int) Math.abs(prefix - expected);
            int localExcess = machines[i] - target;
            answer = Math.max(answer, Math.max(boundaryFlow, localExcess));
        }
        return answer;
    }
}

class Solution {
    public int findMinMoves(int[] machines) {
        int n = machines.length;
        long total = 0;
        for (int dresses : machines) total += dresses;
        if (total % n != 0) return -1;
        long target = total / n;

        long leftSum = 0;
        long answer = 0;
        for (int i = 0; i < n; i++) {
            long rightSum = total - leftSum - machines[i];
            long leftNeed = (long) i * target - leftSum;
            long rightNeed = (long) (n - i - 1) * target - rightSum;
            if (leftNeed > 0 && rightNeed > 0) {
                answer = Math.max(answer, leftNeed + rightNeed);
            } else {
                answer = Math.max(answer, Math.max(Math.abs(leftNeed), Math.abs(rightNeed)));
            }
            leftSum += machines[i];
        }
        return (int) answer;
    }
}

class Solution {
    public int findMinMoves(int[] machines) {
        int n = machines.length;
        long total = 0;
        for (int dresses : machines) total += dresses;
        if (total % n != 0) return -1;
        int target = (int) (total / n);

        int[] transfer = new int[Math.max(0, n - 1)];
        int prefixBalance = 0;
        for (int i = 0; i < n - 1; i++) {
            prefixBalance += machines[i] - target;
            transfer[i] = prefixBalance;
        }

        int answer = 0;
        for (int flow : transfer) answer = Math.max(answer, Math.abs(flow));
        for (int dresses : machines) answer = Math.max(answer, dresses - target);
        return answer;
    }
}

class Solution {
    public int findMinMoves(int[] machines) {
        long total = 0;
        for (int dresses : machines) total += dresses;
        int n = machines.length;
        if (total % n != 0) return -1;
        int target = (int) (total / n);

        int low = 0;
        int high = (int) total;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canFinish(machines, target, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private boolean canFinish(int[] machines, int target, int moves) {
        int balance = 0;
        for (int dresses : machines) {
            int delta = dresses - target;
            balance += delta;
            if (delta > moves) return false;
            if (Math.abs(balance) > moves) return false;
        }
        return true;
    }
}
